<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$token=(string)($_GET['token']??'');$ok=false;$msg='Doğrulama bağlantısı geçersiz veya süresi dolmuş.';if(strlen($token)>=40){$hash=hash('sha256',$token);$pdo=db();$s=$pdo->prepare('SELECT * FROM email_verifications WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW()');$s->execute([$hash]);$r=$s->fetch();if($r){$pdo->beginTransaction();try{$pdo->prepare('UPDATE users SET email_verified_at=NOW() WHERE id=?')->execute([$r['user_id']]);$pdo->prepare('UPDATE email_verifications SET used_at=NOW() WHERE id=?')->execute([$r['id']]);$pdo->commit();$ok=true;$msg='E-posta adresin doğrulandı. Artık giriş yapabilirsin.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('verify email: '.$e->getMessage());}}}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>E-posta doğrulama · Loopi Makarna</title><link rel="stylesheet" href="styles.css"></head><body><main class="container" style="padding:70px 20px"><div class="card" style="max-width:560px;margin:auto;padding:30px"><h1><?=$ok?'Doğrulama tamamlandı':'Doğrulama başarısız'?></h1><p><?=htmlspecialchars($msg)?></p><a class="btn primary" href="index.php">Mağazaya dön</a></div></main></body></html>
